/**
 * MX4: the dungeon cards' data (core/dungeons.json, CR 309), generated by scripts/gen-dungeons.ts. Every room ability is what the game compiler makes of the
 * room's Oracle text today (so the file follows the template set), and the rooms form the graph CR 309.4-309.5 describe.
 */
import { describe, expect, it } from 'vitest';
import { roomAbility } from '../../../../scripts/gen-dungeons';
import { DUNGEONS } from '../../src/core/dungeon-data';
import { dungeonDef } from '../../src/core/dungeons';

describe('CR 309: the dungeon cards', () => {
  it('the three dungeons of venture into the dungeon and Undercity (CR 701.49d) are there', () => {
    expect(DUNGEONS.map((d) => d.name)).toEqual(['Dungeon of the Mad Mage', 'Lost Mine of Phandelver', 'Tomb of Annihilation', 'Undercity']);
    expect(DUNGEONS.find((d) => d.name === 'Undercity')!.subtypes).toEqual(['Undercity']);
  });

  it('CR 309.4a, 309.5a: room 0 is the topmost room, every arrow points down to an existing room, one bottommost room, every room reachable', () => {
    for (const d of DUNGEONS) {
      const n = d.rooms.length;
      for (const r of d.rooms) for (const i of r.next) expect(i, `${d.name}: ${r.name}`).toBeGreaterThan(d.rooms.indexOf(r));
      for (const r of d.rooms) for (const i of r.next) expect(i).toBeLessThan(n);
      expect(d.rooms.filter((r) => r.next.length === 0), d.name).toHaveLength(1);
      expect(d.rooms.some((r) => r.next.includes(0)), d.name).toBe(false);
      const seen = new Set([0]);
      for (let i = 0; i < n; i++) if (seen.has(i)) for (const j of d.rooms[i]!.next) seen.add(j);
      expect(seen.size, d.name).toBe(n);
    }
  });

  it('CR 309.4c: each stored room ability is what the compiler makes of the room text now (regenerate with scripts/gen-dungeons.ts)', () => {
    for (const d of DUNGEONS) {
      for (const r of d.rooms) {
        const now = roomAbility(r.text);
        expect(r.ability, `${d.name}: ${r.name}`).toEqual(now.ability);
        expect(r.level, `${d.name}: ${r.name}`).toBe(now.level);
      }
    }
  });

  it('the definition: type Dungeon, rooms as abilities in room order that function in the command zone, level computed from the rooms', () => {
    const lost = dungeonDef(DUNGEONS.find((d) => d.name === 'Lost Mine of Phandelver')!);
    expect(lost.id).toBe('dungeon:Lost Mine of Phandelver');
    expect(lost.faces[0]!.types).toEqual(['Dungeon']);
    expect(lost.faces[0]!.abilities).toHaveLength(7);
    expect(lost.faces[0]!.abilities.every((a) => (a as { zone?: string[] }).zone?.[0] === 'command')).toBe(true);
    expect(lost.automation.level).toBe('full');
    expect(dungeonDef(DUNGEONS.find((d) => d.name === 'Tomb of Annihilation')!).automation.level).toBe('partial');
  });
});
